import type { OperationalJobPriority } from "./maritime";

export type WorkflowEvidence = {
  sourceType: string;
  sourceId: string;
  label: string;
  href?: string;
  excerpt?: string;
};

export type WorkflowJobDraft = {
  jobType: string;
  priority: OperationalJobPriority;
  title: string;
  summary: string;
  evidence: WorkflowEvidence[];
