      severity: "medium",
      description: "Berth delay and anchorage waiting time may affect laytime.",
    },
  ],
  complianceFlag: {
    id: "CFL-1",
    euEtsExposure: true,
    fueleuRisk: false,
    mrvMissingData: true,
