+async function generateReconciliationWorkflow(workspaceId: string, context: WorkflowContext) {
+  const extractions = extractDocumentFields(context);
+  const findings = buildReconciliationFindings(context);
+  await persistDocumentExtractions(workspaceId, extractions);
+  await persistReconciliationFindings(workspaceId, findings);
+  return persistWorkflowJobs(workspaceId, context.voyage.id, buildAiActionPlanJobs(context, findings));
+}
+
+async function generateChangeMonitorWorkflow(workspaceId: string, context: WorkflowContext) {
+  const previous = await loadVoyageSnapshot(workspaceId, context.voyage.id);
+  const change = compareVoyageSnapshots(context, previous);
+  const snapshot = buildVoyageSnapshot(context);
+  await persistVoyageSnapshot(workspaceId, snapshot);
+  await persistReconciliationFindings(workspaceId, change.changes);
+  return persistWorkflowJobs(
+    workspaceId,
+    context.voyage.id,
+    change.changes
+      .filter((finding) => finding.confidence >= 0.75)
+      .map((finding) => ({
+        jobType: "voyage_change",
+        priority: finding.severity,
+        title: finding.title,
+        summary: finding.summary,
+        evidence: finding.evidence,
+        payload: { ...finding.payload, confidence: finding.confidence, suggestedAction: finding.suggestedAction },
+      })),
+  );
+}
+
+async function generateAuditWorkflow(workspaceId: string, context: WorkflowContext) {
+  const findings = buildReconciliationFindings(context);
+  const auditChecks = buildAuditChecks(context, findings);
+  await persistReconciliationFindings(workspaceId, findings);
+  return persistWorkflowJobs(
+    workspaceId,
+    context.voyage.id,
+    auditChecks
+      .filter((check) => !check.passed && check.severity !== "low")
+      .map((check) => ({
+        jobType: "audit_warning",
+        priority: check.severity,
+        title: `${check.title} for ${context.voyage.id}`,
+        summary: check.summary,
+        evidence: check.evidence,
+        payload: { auditKey: check.key },
+      })),
+  );
+}
+
+function buildSourceConfidence(context: WorkflowContext) {
+  return [
+    ...context.documents.map((document) => ({
+      ...scoreSourceConfidence("file", document.documentType),
+      sourceId: document.id,
+      sourceType: "file",
